CREATE TYPE "Role" AS ENUM ('USER','DESIGNER','ADMIN','SUPER_ADMIN');
CREATE TYPE "ProjectStatus" AS ENUM ('DRAFT','ACTIVE','ARCHIVED');
CREATE TYPE "JobStatus" AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED');
CREATE TYPE "JobType" AS ENUM ('ROOM_UNDERSTANDING','DESIGN_GENERATION','DESIGN_REVISION','THREE_D_SCENE','PANORAMA','WALKTHROUGH','VIDEO');
CREATE TYPE "AssetType" AS ENUM ('FLOOR_PLAN','ROOM_IMAGE','DESIGN_IMAGE','PANORAMA','THREE_D_SCENE','WALKTHROUGH','VIDEO','OTHER');
CREATE TYPE "PurchaseStatus" AS ENUM ('CREATED','PAID','FAILED','REFUNDED','CANCELLED');
CREATE TYPE "PaymentStatus" AS ENUM ('CREATED','AUTHORIZED','CAPTURED','FAILED','REFUNDED');
CREATE TYPE "EntitlementStatus" AS ENUM ('RESERVED','ACTIVE','CONSUMED','RELEASED','EXPIRED');
CREATE TYPE "BoqStatus" AS ENUM ('DRAFT','FINALIZED');
CREATE TYPE "RoomType" AS ENUM ('LIVING_ROOM','BEDROOM','KITCHEN','BATHROOM','DINING_ROOM','BALCONY','STUDY','OTHER');

CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"name" TEXT,"image" TEXT,"role" "Role" NOT NULL DEFAULT 'USER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Account" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" TEXT NOT NULL,"provider" TEXT NOT NULL,"providerAccountId" TEXT NOT NULL,"refresh_token" TEXT,"access_token" TEXT,"expires_at" INTEGER,"token_type" TEXT,"scope" TEXT,"id_token" TEXT,"session_state" TEXT,CONSTRAINT "Account_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Account_provider_providerAccountId_key" ON "Account"("provider","providerAccountId"); CREATE INDEX "Account_userId_idx" ON "Account"("userId");
CREATE TABLE "Session" ("id" TEXT NOT NULL,"sessionToken" TEXT NOT NULL,"userId" TEXT NOT NULL,"expires" TIMESTAMP(3) NOT NULL,CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Session_sessionToken_key" ON "Session"("sessionToken"); CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE TABLE "VerificationToken" ("identifier" TEXT NOT NULL,"token" TEXT NOT NULL,"expires" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "VerificationToken_token_key" ON "VerificationToken"("token"); CREATE UNIQUE INDEX "VerificationToken_identifier_token_key" ON "VerificationToken"("identifier","token");
CREATE TABLE "Property" ("id" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"name" TEXT NOT NULL,"address" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Property_pkey" PRIMARY KEY ("id")); CREATE INDEX "Property_ownerId_createdAt_idx" ON "Property"("ownerId","createdAt");
CREATE TABLE "Asset" ("id" TEXT NOT NULL,"type" "AssetType" NOT NULL,"objectKey" TEXT NOT NULL,"contentType" TEXT NOT NULL,"sizeBytes" BIGINT,"checksum" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"designVersionId" TEXT,CONSTRAINT "Asset_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Asset_objectKey_key" ON "Asset"("objectKey"); CREATE INDEX "Asset_type_createdAt_idx" ON "Asset"("type","createdAt");
CREATE TABLE "FloorPlan" ("id" TEXT NOT NULL,"propertyId" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"assetId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FloorPlan_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "FloorPlan_propertyId_version_key" ON "FloorPlan"("propertyId","version"); CREATE INDEX "FloorPlan_propertyId_idx" ON "FloorPlan"("propertyId");
CREATE TABLE "Room" ("id" TEXT NOT NULL,"propertyId" TEXT NOT NULL,"type" "RoomType" NOT NULL,"name" TEXT NOT NULL,"areaSqFt" DECIMAL(12,2),"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Room_pkey" PRIMARY KEY ("id")); CREATE INDEX "Room_propertyId_idx" ON "Room"("propertyId");
CREATE TABLE "DesignProject" ("id" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"propertyId" TEXT NOT NULL,"roomId" TEXT,"name" TEXT NOT NULL,"status" "ProjectStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DesignProject_pkey" PRIMARY KEY ("id")); CREATE INDEX "DesignProject_ownerId_createdAt_idx" ON "DesignProject"("ownerId","createdAt"); CREATE INDEX "DesignProject_propertyId_idx" ON "DesignProject"("propertyId");
CREATE TABLE "DesignVersion" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"version" INTEGER NOT NULL,"prompt" TEXT,"parameters" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DesignVersion_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "DesignVersion_projectId_version_key" ON "DesignVersion"("projectId","version"); CREATE INDEX "DesignVersion_projectId_idx" ON "DesignVersion"("projectId");
CREATE TABLE "AIJob" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"type" "JobType" NOT NULL,"status" "JobStatus" NOT NULL DEFAULT 'QUEUED',"idempotencyKey" TEXT NOT NULL,"provider" TEXT,"providerJobId" TEXT,"input" JSONB,"output" JSONB,"errorCode" TEXT,"errorMessage" TEXT,"attempts" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),CONSTRAINT "AIJob_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "AIJob_projectId_idempotencyKey_key" ON "AIJob"("projectId","idempotencyKey"); CREATE INDEX "AIJob_status_createdAt_idx" ON "AIJob"("status","createdAt"); CREATE INDEX "AIJob_provider_providerJobId_idx" ON "AIJob"("provider","providerJobId");
CREATE TABLE "CatalogueItem" ("id" TEXT NOT NULL,"sku" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"category" TEXT NOT NULL,"unit" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CatalogueItem_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "CatalogueItem_sku_key" ON "CatalogueItem"("sku");
CREATE TABLE "CataloguePrice" ("id" TEXT NOT NULL,"itemId" TEXT NOT NULL,"amountMinor" BIGINT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'INR',"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),CONSTRAINT "CataloguePrice_pkey" PRIMARY KEY ("id")); CREATE INDEX "CataloguePrice_itemId_effectiveFrom_idx" ON "CataloguePrice"("itemId","effectiveFrom");
CREATE TABLE "Package" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"priceMinor" BIGINT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'INR',"credits" INTEGER NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Package_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Package_code_key" ON "Package"("code");
CREATE TABLE "Purchase" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"packageId" TEXT NOT NULL,"status" "PurchaseStatus" NOT NULL DEFAULT 'CREATED',"amountMinor" BIGINT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'INR',"provider" TEXT,"providerOrderId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Purchase_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Purchase_providerOrderId_key" ON "Purchase"("providerOrderId"); CREATE INDEX "Purchase_userId_createdAt_idx" ON "Purchase"("userId","createdAt");
CREATE TABLE "Payment" ("id" TEXT NOT NULL,"purchaseId" TEXT NOT NULL,"status" "PaymentStatus" NOT NULL DEFAULT 'CREATED',"providerPaymentId" TEXT,"amountMinor" BIGINT NOT NULL,"currency" TEXT NOT NULL,"signature" TEXT,"rawEventHash" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Payment_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Payment_purchaseId_key" ON "Payment"("purchaseId"); CREATE UNIQUE INDEX "Payment_providerPaymentId_key" ON "Payment"("providerPaymentId"); CREATE INDEX "Payment_status_createdAt_idx" ON "Payment"("status","createdAt");
CREATE TABLE "Entitlement" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"purchaseId" TEXT,"packageId" TEXT NOT NULL,"status" "EntitlementStatus" NOT NULL DEFAULT 'ACTIVE',"creditsTotal" INTEGER NOT NULL,"creditsReserved" INTEGER NOT NULL DEFAULT 0,"creditsConsumed" INTEGER NOT NULL DEFAULT 0,"idempotencyKey" TEXT NOT NULL,"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Entitlement_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Entitlement_userId_idempotencyKey_key" ON "Entitlement"("userId","idempotencyKey"); CREATE INDEX "Entitlement_userId_status_idx" ON "Entitlement"("userId","status");
CREATE TABLE "Boq" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"status" "BoqStatus" NOT NULL DEFAULT 'DRAFT',"currency" TEXT NOT NULL DEFAULT 'INR',"subtotalMinor" BIGINT NOT NULL DEFAULT 0,"taxMinor" BIGINT NOT NULL DEFAULT 0,"discountMinor" BIGINT NOT NULL DEFAULT 0,"wastageMinor" BIGINT NOT NULL DEFAULT 0,"totalMinor" BIGINT NOT NULL DEFAULT 0,"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Boq_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Boq_projectId_version_key" ON "Boq"("projectId","version");
CREATE TABLE "BoqLine" ("id" TEXT NOT NULL,"boqId" TEXT NOT NULL,"catalogueItemId" TEXT,"description" TEXT NOT NULL,"quantity" DECIMAL(14,4) NOT NULL,"unit" TEXT NOT NULL,"unitPriceMinor" BIGINT NOT NULL,"labourMinor" BIGINT NOT NULL DEFAULT 0,"materialMinor" BIGINT NOT NULL DEFAULT 0,"taxRateBps" INTEGER NOT NULL DEFAULT 0,"wastageBps" INTEGER NOT NULL DEFAULT 0,"discountMinor" BIGINT NOT NULL DEFAULT 0,"lineTotalMinor" BIGINT NOT NULL,CONSTRAINT "BoqLine_pkey" PRIMARY KEY ("id")); CREATE INDEX "BoqLine_boqId_idx" ON "BoqLine"("boqId");
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"userId" TEXT,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT,"requestId" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id")); CREATE INDEX "AuditLog_entity_entityId_createdAt_idx" ON "AuditLog"("entity","entityId","createdAt"); CREATE INDEX "AuditLog_userId_createdAt_idx" ON "AuditLog"("userId","createdAt");
